         \Vertex[LabelOut,Lpos=0,x=1 ,y=1,L=${\color{blue} \sigma(\vec{e}_i+\vec{e}_{d+1})=h_\emptyset }$]{4}                   
    \Edge[style={thick},color=black](1)(2)
